#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>
#include <immintrin.h>
static const uint64_t N = 1200ULL<<20; static uint8_t *buf; static volatile uint64_t sink[64];
typedef struct {size_t off, len; int id;} job_t;
static void* run(void*a){ job_t*j=a; __m256i acc=_mm256_setzero_si256();
  for(int rep=0;rep<3;rep++) for(size_t i=j->off;i<j->off+j->len;i+=128){
    acc=_mm256_add_epi32(acc,_mm256_load_si256((__m256i*)(buf+i)));
    acc=_mm256_add_epi32(acc,_mm256_load_si256((__m256i*)(buf+i+32)));
    acc=_mm256_add_epi32(acc,_mm256_load_si256((__m256i*)(buf+i+64)));
    acc=_mm256_add_epi32(acc,_mm256_load_si256((__m256i*)(buf+i+96)));}
  sink[j->id]=_mm256_extract_epi64(acc,0); return 0;}
static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec*1e-9;}
int main(){ buf=aligned_alloc(4096,N); for(uint64_t i=0;i<N;i+=4096) buf[i]=i;
  for(int nt=1; nt<=16; nt*=2){ pthread_t th[16]; job_t jb[16]; size_t chunk=(N/nt)&~127ULL;
    double t0=now(); for(int t=0;t<nt;t++){jb[t]=(job_t){t*chunk,chunk,t}; pthread_create(&th[t],0,run,&jb[t]);}
    for(int t=0;t<nt;t++) pthread_join(th[t],0); double dt=now()-t0;
    printf("threads=%2d  %.1f GB/s (3 passes)\n", nt, 3.0*N/dt/1e9); }
  return 0;}
EOF
gcc -O2 -mavx2 -pthread bw.c -o bw && ./bw

